#!/usr/bin/env ruby
# Write EDG's win64 predefined-macro table from MinGW-w64's gcc: scripts/win-predef.rb OUT [CC]
# EDG's own lib_win64 table is Microsoft's (generated by make_win_predef_macro): it lacks the gcc type macros that lib/cstdint
# needs (__INT8_TYPE__ ...), so the generated C does not compile with MinGW. This table is the output of
# `x86_64-w64-mingw32-gcc -dM -E`, in the format of the other lib_* tables (tag gnu, flag no).
# Dropped: function-like macros, and the names EDG defines itself or that GCC-only headers need no table for (__cplusplus, __cpp_*,
# __STDC_*, __CHAR16_TYPE__, __WCHAR_TYPE__, __GNUC__ and the gcc version macros): EDG rejects some of them redefined. See docs/notes/freestanding.md, "Windows".
# Ported from scripts/win-predef.sh. The exit status is the pipeline's: the compiler's, or 1 when no macro is kept.

require "open3"

DEFAULT_CC = "x86_64-w64-mingw32-gcc"
FUNCTION_LIKE = /\A#define [A-Za-z_][A-Za-z0-9_]*\(/
DROP = /\A(__cplusplus|__cpp_|__STDC|__CHAR16_TYPE__|__WCHAR_TYPE__|__GNUC|__GNUG|__GXX|__VERSION__|__OPTIMIZE|__CET__|__SEH__|__GCC)/

# Runs the compiler; returns its stdout and exit status (127 when it cannot be run, as the shell reports).
def run_cc(cc)
  out, err, status = Open3.capture3(cc, "-dM", "-E", "-x", "c++", "-std=c++23", "/dev/null")
  $stderr.binmode.write(err)
  [out, status.exitstatus || 128 + status.termsig]
rescue Errno::ENOENT
  $stderr.puts "win-predef: #{cc}: command not found"
  ["", 127]
end

out_path = ARGV[0]
if out_path.nil?
  warn "usage: scripts/win-predef.rb OUT [CC]"
  exit 1
end
cc = ARGV[1]
cc = DEFAULT_CC if cc.nil? || cc.empty?

cc_out, cc_status = run_cc(cc)

# awk 1: "#define NAME VALUE" becomes "NAME<TAB>VALUE"; a macro without a value is 1.
# awk 2: the entries are split on tabs and printed as gnu/no tables.
entries = []
cc_out.each_line do |raw|
  line = raw.delete_suffix("\n")
  next if FUNCTION_LIKE.match?(line)
  next unless line.start_with?("#define ")
  name = line.sub(/\A[ \t\n]+/, "").split(/[ \t\n]+/)[1].to_s
  value = line.sub(/\A#define [^ ]+ ?/, "")
  value = "1" if value.empty?
  entry = "#{name}\t#{value}"
  next if DROP.match?(entry)
  parts = entry.split("\t", -1)
  entries << "gnu no  #{parts[0]} #{parts[1]}"
end

header = "# MinGW-w64 x86-64: #{cc} -dM -E (scripts/win-predef.rb)"
File.binwrite(out_path, ([header] + entries).map { |l| "#{l}\n" }.join)

# With pipefail, the pipeline's status is its rightmost failing stage: grep -v fails when it selects nothing.
exit 1 if entries.empty?
exit cc_status
